function splitRollRecipe(recipe){
 const {legacyRolls,...source}=recipe;
 const sharedSteps=recipe.steps.filter(step=>!/^For (?:rice-paper|tortilla) rolls/i.test(step)&&!/^The filling is shared/i.test(step));
 return [
  {...source,id:"rolls-rice-paper",name:"Paneer rolls (Rice paper)",servings:2,ingredients:recipe.ingredients.filter(item=>!/tortilla/i.test(item[0])),steps:[...sharedSteps,"For rice-paper rolls, soften one sheet at a time in warm water, add filling and fold.","The shared filling makes 2 rice-paper rolls."]},
  {...source,id:"rolls-tortilla",name:"Paneer rolls (Tortilla)",servings:3,ingredients:recipe.ingredients.filter(item=>!(/rice[ -]?paper/i.test(item[0]))),steps:[...sharedSteps,"For tortilla rolls, warm the wrap, add filling and dressing, then roll tightly.","The shared filling makes 3 tortilla rolls."]}
 ];
}
function isSeparateRollRecipe(recipe,variant){
 if(recipe?.legacyRolls||recipe?.id==="rolls")return false;
 const name=String(recipe?.name||"").toLowerCase();
 if(!/paneer rolls?/.test(name)||/rice paper.*tortilla|tortilla.*rice paper/.test(name))return false;
 return variant==="rice-paper"?/rice[ -]?paper/.test(name):/tortilla/.test(name);
}

function recipeIngredientFallback(recipe, ingredient, preferredTemplate) {
 const template=preferredTemplate||seed.find(item=>item.id===recipe?.id)||((recipe?.id==="rolls-rice-paper"||recipe?.id==="rolls-tortilla"||/paneer rolls/i.test(recipe?.name||""))?seed.find(item=>item.id==="rolls"):null);
 const name=String(ingredient?.[0]||"").trim().toLowerCase();
 const exact=template?.ingredients?.find(item=>String(item[0]||"").trim().toLowerCase()===name);
 if(exact)return exact;
 if(template?.id==="rolls"&&/tortilla/i.test(name))return template.ingredients.find(item=>/tortilla/i.test(item[0]));
 return undefined;
}

