 function updateIngredient(i,j,v){
   setForm(f=>({...f,ingredients:f.ingredients.map((x,k)=>{
     if(k!==i) return x;
     const fallback=recipeIngredientFallback(form,x);
     const next=withIngredientNutritionRates(x,fallback);
     if(j===1 || j===2){
       next[j]=j===1?(Number(v)||0):v;
       const entry=INGREDIENT_DB.find(item=>item.id===next[10]);
       if(entry){
         const vals=dbNutritionForQuantity(entry,next[1],next[2]);
         next[3]=vals[0]; next[4]=vals[1]; next[5]=vals[2]; next[6]=vals[3];
         dbNutritionForQuantity(entry,1,next[2]).forEach((rate,index)=>next[11+index]=rate);
       } else if(j===1){
         [3,4,5,6].forEach((col,index)=>{next[col]=Math.round((next[11+index]*next[1])*100)/100;});
       } else if(Number(next[1])>0){
         [3,4,5,6].forEach((col,index)=>next[11+index]=(Number(next[col])||0)/Number(next[1]));
       }
     } else if(j===0) {
       next[0]=v;
       const match=matchIngredientDatabase(v);
       if(match){next[10]=match.id;next[8]="database";const vals=dbNutritionForQuantity(match,next[1],next[2]);next[3]=vals[0];next[4]=vals[1];next[5]=vals[2];next[6]=vals[3];dbNutritionForQuantity(match,1,next[2]).forEach((rate,index)=>next[11+index]=rate);}
       else {next[10]="";}
     } else {
       next[j]=Number(v)||0;
       next[j+8]=Number(next[1])>0?next[j]/Number(next[1]):next[j];
       if(j===6){next[8]="verified";next[9]=false;next[10]="";}
       else if(j>=3 && j<=5){next[8]="custom";next[10]="";}
     }
     return next;
   })}));
 }

